package ru.ryadom.calendar;
import org.junit.Test;import java.util.*;import static org.junit.Assert.*;
public class OverlapPlanTest {
 Event e(int from,int to){Event e=new Event();e.start=from*60000L;e.end=to*60000L;return e;}
 @Test public void requestedNestedGeometry(){Event small=e(720,780),middle=e(660,840),large=e(660,900);OverlapPlan p=new OverlapPlan(Arrays.asList(small,middle,large));assertEquals(3,p.columns);for(OverlapPlan.Placement item:p.items){assertEquals(item.event==small?.5f:0,item.top,0.001);assertEquals(item.event==small?1f:item.event==middle?2f:2.5f,item.height,0.001);}}
 @Test public void partialAndIdentical(){OverlapPlan p=new OverlapPlan(Arrays.asList(e(660,780),e(720,840)));assertEquals(0,p.items.get(0).top,0.001);assertEquals(.5,p.items.get(1).top,0.001);assertEquals(1.5,p.items.get(0).height,0.001);assertEquals(1.5,p.items.get(1).height,0.001);OverlapPlan equal=new OverlapPlan(Arrays.asList(e(720,780),e(720,780)));assertEquals(1,equal.height,0.001);}
 @Test public void fiveMinutesInclusiveWithoutChaining(){OverlapPlan same=new OverlapPlan(Arrays.asList(e(900,960),e(905,965)));assertEquals(1,same.height,0.001);OverlapPlan different=new OverlapPlan(Arrays.asList(e(900,960),e(906,966)));assertEquals(2,different.height,0.001);List<Event> events=Arrays.asList(e(900,960),e(905,960),e(910,960));Map<Long,Long> aligned=OverlapPlan.aligned(events,true);assertEquals(Long.valueOf(900*60000L),aligned.get(905*60000L));assertEquals(Long.valueOf(910*60000L),aligned.get(910*60000L));}
 @Test public void endToleranceAndOriginalTimes(){Event first=e(900,960),within=e(900,965),outside=e(900,966);OverlapPlan aligned=new OverlapPlan(Arrays.asList(first,within));assertEquals(1,aligned.height,0.001);assertEquals(965*60000L,within.end);OverlapPlan separate=new OverlapPlan(Arrays.asList(first,outside));assertEquals(1.5,separate.height,0.001);assertEquals(1,separate.items.get(0).height,0.001);assertEquals(1.5,separate.items.get(1).height,0.001);}
}
